+    let native = unsafe { &*device.as_ptr().cast::<AnyObject>() };
+    let descriptor = unsafe { &*descriptor.as_ptr().cast::<AnyObject>() };
+    let raw: *mut AnyObject =
+        unsafe { objc2::msg_send![native, newTextureWithDescriptor: descriptor] };
